class Solution {
public:
    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {
        unordered_map<int, int> inMap;
        for (int i = 0; i < (int)inorder.size(); i++) inMap[inorder[i]] = i;
        int postIdx = (int)postorder.size() - 1;
        return helper(postorder, inMap, postIdx, 0, (int)inorder.size() - 1);
    }
private:
    TreeNode* helper(vector<int>& postorder, unordered_map<int, int>& inMap, int& postIdx, int left, int right) {
        if (left > right) return nullptr;
        int rootVal = postorder[postIdx--];
        TreeNode* root = new TreeNode(rootVal);
        int mid = inMap[rootVal];
        root->right = helper(postorder, inMap, postIdx, mid + 1, right);
        root->left = helper(postorder, inMap, postIdx, left, mid - 1);
        return root;
    }
};

class Solution {
    private int postIdx;
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        Map<Integer, Integer> inMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) inMap.put(inorder[i], i);
        postIdx = postorder.length - 1;
        return helper(postorder, inMap, 0, inorder.length - 1);
    }
    private TreeNode helper(int[] postorder, Map<Integer, Integer> inMap, int left, int right) {
        if (left > right) return null;
        int rootVal = postorder[postIdx--];
        TreeNode root = new TreeNode(rootVal);
        int mid = inMap.get(rootVal);
        root.right = helper(postorder, inMap, mid + 1, right);
        root.left = helper(postorder, inMap, left, mid - 1);
        return root;
    }
}

var buildTree = function(inorder, postorder) {
    const inMap = new Map();
    for (let i = 0; i < inorder.length; i++) inMap.set(inorder[i], i);
    let postIdx = postorder.length - 1;
    function helper(left, right) {
        if (left > right) return null;
        const rootVal = postorder[postIdx--];
        const root = new TreeNode(rootVal);
        const mid = inMap.get(rootVal);
        root.right = helper(mid + 1, right);
        root.left = helper(left, mid - 1);
